const req=$('Prepare Request').first().json;const base=(Date.now()-1750000000000)*1000;let n=0;
const mk=(Type,Stage,Level,Message,P)=>{let j=P?JSON.stringify(P):'';if(j.length>45000){delete P.Email_Body_HTML;j=JSON.stringify(P);}return {json:{Run_ID:req.run_id,Seq:String(base+n++),Type,Stage,Level,Message,Payload:j}};};
return [mk('stage','start','info','Search started for "'+req.search_query+'". Searching Google Maps now - first results appear in 1-3 minutes...')];

// ====== SETTINGS (service owner): apne clients ke access codes yahan likhein ======
const ACCESS_CODES = ['ali'];
const MAX_LEADS = 100;
// ================================================================================
const raw = $input.first().json || {};
const b = raw.body || raw;
const s = (v) => (v === undefined || v === null) ? '' : String(v).trim();
const reject = (msg, code) => [{ json: { valid: false, status_code: code || 400, error: msg } }];
if (!ACCESS_CODES.includes(s(b.access_code))) return reject('Invalid access code.', 401);
const runId = s(b.run_id);
if (!/^[A-Za-z0-9_-]{8,64}$/.test(runId)) return reject('Invalid request id.');
const userName = s(b.user_name), userEmail = s(b.user_email), services = s(b.services);
const niche = s(b.niche), area = s(b.area), country = s(b.country);
if (!userName || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(userEmail) || !services || !niche || !area || !country) return reject('Please fill in all required fields.');
let n = parseInt(b.max_leads, 10);
if (!n || n < 1) n = 20;
if (n > MAX_LEADS) n = MAX_LEADS;
const arr = (v) => Array.isArray(v) ? v.map(x => s(x)).filter(Boolean).slice(-5000) : [];
const k = (b.known && typeof b.known === 'object') ? b.known : {};
const known = { ids: arr(k.ids), domains: arr(k.domains).map(x => x.toLowerCase()), phones: arr(k.phones) };
const sheetId = /^[A-Za-z0-9_-]{20,100}$/.test(s(b.sheet_id)) ? s(b.sheet_id) : '';
const sheetTab = s(b.sheet_tab).slice(0, 100) || 'Sheet1';
return [{ json: {
  valid: true,
  run_id: runId,
  user_name: userName,
  company: s(b.company) || userName,
  user_email: userEmail,
  user_phone: s(b.user_phone),
  portfolio: s(b.portfolio),
  services: services,
  niche: niche,
  area: area,
  country: country,
  max_leads: n,
  check_social: b.check_social === true || /^(yes|true)$/i.test(s(b.check_social)),
  email_summary: b.email_summary === true,
  known: known,
  sheet_id: sheetId,
  sheet_tab: sheetTab,
  search_query: niche + ' in ' + area + ', ' + country
} }];

const req = $('Prepare Request').first().json;
const rawAll = $('Run Google Maps Scraper').all().map(i => i.json);
const raw = rawAll.filter(p => p && p.title);
const apifyErr = rawAll.find(p => p && p.error);
let existing = [];
try { existing = $('Read Existing Leads').all().map(i => i.json).filter(r => r && r.Lead_ID); } catch (e) { existing = []; }

const AGG = ['facebook.com','fb.com','instagram.com','linkedin.com','twitter.com','x.com','youtube.com','tiktok.com','linktr.ee','wa.me','google.com','business.site','marham.pk','instacare.pk','oladoc.com','sehat.com.pk','apkamuaalij.com','yellowpages.com','justdial.com','yelp.com','tripadvisor.com','foursquare.com','pakistanbusinessdirectory.com'];
const SOC = { facebook: ['facebook.com','fb.com'], instagram: ['instagram.com'], linkedin: ['linkedin.com'], twitter: ['twitter.com','x.com'], youtube: ['youtube.com'], tiktok: ['tiktok.com'] };
const host = (u) => { try { return new URL(/^https?:/i.test(u) ? u : 'https://' + u).hostname.replace(/^www\./, '').toLowerCase(); } catch (e) { return ''; } };
const inList = (h, list) => list.some(d => h === d || h.endsWith('.' + d));
const digits = (s) => String(s || '').replace(/\D/g, '');
const phoneKey = (s) => { const d = digits(s); return d.length >= 7 ? d.slice(-9) : ''; };
const hash = (s) => { let h = 5381; for (let i = 0; i < s.length; i++) { h = ((h << 5) + h + s.charCodeAt(i)) | 0; } return 'L' + (h >>> 0).toString(16); };

const GOV_HOST = [/(^|\.)(gov|mil)(\.[a-z]{2})?$/, /(^|\.)(gob|gouv|govt|gv|gub|go|nic|gc|admin)\.[a-z]{2}$/, /(^|\.)bund\.de$/];
const GOV_WORDS = /\b(government|governmental|govt|municipal|municipality|embassy|consulate|police|city hall|town hall|courthouse|ministry|commissioner|tehsil|dhq|thq|civil hospital|public library|parliament|secretariat|revenue office|post office|fire station|army|military|cantonment|union council|city council|nadra|wapda|passport office)\b/i;
const isGov = (p) => {
  const h = host(String(p.website || ''));
  if (h && GOV_HOST.some(r => r.test(h))) return true;
  const txt = [p.categoryName].concat(p.categories || []).concat([p.title]).join(' ');
  return GOV_WORDS.test(txt);
};

const exIds = new Set(), exDomains = new Set(), exPhones = new Set();
for (const r of existing) {
  if (r.Lead_ID) exIds.add(String(r.Lead_ID));
  const d = host(r.Website || ''); if (d) exDomains.add(d);
  const p = phoneKey(r.Phone); if (p) exPhones.add(p);
}

const kn = req.known || {};
(kn.ids || []).forEach(x => exIds.add(String(x)));
(kn.domains || []).forEach(x => exDomains.add(String(x)));
(kn.phones || []).forEach(x => exPhones.add(String(x)));

// competitor pool = every place found in this search
const pool = raw.filter(p => !isGov(p)).map(p => {
  let w = (p.website || '').trim(); let h = host(w);
  if (h && (inList(h, AGG))) { w = ''; h = ''; }
  return { id: String(p.placeId || ''), name: p.title, rating: p.totalScore || '', reviews: p.reviewsCount || 0, website: h, has_website: !!h };
});

const seen = new Set();
const stats = { raw: raw.length, duplicates: 0, unreachable: 0, government: 0 };
const leads = [];
for (const p of raw) {
  if (isGov(p)) { stats.government++; continue; }
  let website = (p.website || '').trim();
  let h = host(website);
  const social = { facebook: '', instagram: '', linkedin: '', twitter: '', youtube: '', tiktok: '' };
  if (h) {
    for (const k of Object.keys(SOC)) { if (inList(h, SOC[k])) { social[k] = website; website = ''; h = ''; break; } }
  }
  if (h && inList(h, AGG)) { website = ''; h = ''; }
  if (website && !/^https?:/i.test(website)) website = 'https://' + website;
  const phone = String(p.phone || p.phoneUnformatted || '').trim();
  const pk = phoneKey(phone);
  const id = hash(String(p.placeId || (p.title + '|' + (p.address || ''))));

  const dupBatch = seen.has(id) || (h && seen.has('d:' + h)) || (pk && seen.has('p:' + pk));
  const dupSheet = exIds.has(id) || (h && exDomains.has(h)) || (pk && exPhones.has(pk));
  if (dupBatch || dupSheet) { stats.duplicates++; continue; }
  if (!website && !phone && !Object.values(social).some(Boolean)) { stats.unreachable++; continue; }
  seen.add(id); if (h) seen.add('d:' + h); if (pk) seen.add('p:' + pk);

  const competitors = pool
    .filter(c => c.name !== p.title && c.rating)
    .sort((a, b) => (b.reviews || 0) - (a.reviews || 0))
    .slice(0, 3);

  leads.push({ json: {
    lead_id: id,
    business_name: p.title,
    category: p.categoryName || (Array.isArray(p.categories) && p.categories[0]) || req.niche,
    address: p.address || '',
    country: req.country,
    phone: phone,
    website: website,
    maps_url: p.url || '',
    rating: p.totalScore || '',
    reviews: p.reviewsCount || 0,
    maps_image: p.imageUrl || '',
    social_from_maps: social,
    competitors: competitors
  } });
  if (leads.length >= req.max_leads) break;
}
if (!leads.length) {
  let msg;
  if (apifyErr && !raw.length) msg = 'The business search service is temporarily unavailable. Please try again in a few minutes.';
  else msg = 'No new leads found. Of ' + stats.raw + ' businesses we found, ' + stats.duplicates + ' were already delivered to you, ' + stats.government + ' were government offices and ' + stats.unreachable + ' had no contact details. Try a different area or business type.';
  return [{ json: { __empty: true, message: msg, stats: stats } }];
}
return leads;

const BAD_EMAIL = /\.(png|jpe?g|gif|webp|svg|css|js|woff2?)$|sentry|wixpress|example\.|domain\.com|yourname|email@email|u003e|@2x/i;
const absUrl = (u, base) => { try { return new URL(u, base).href; } catch (e) { return ''; } };
const stripTags = (h) => h.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();
const bodyOf = (r) => { if (!r) return ''; if (typeof r.body === 'string') return r.body; if (typeof r.data === 'string') return r.data; return ''; };
function extractContacts(html) {
  const emails = new Set(); const phones = new Set();
  for (const m of html.matchAll(/mailto:([^"'?\s>]+)/gi)) {
    let e = ''; try { e = decodeURIComponent(m[1]).toLowerCase().trim(); } catch (x) { e = m[1].toLowerCase().trim(); }
    if (e && !BAD_EMAIL.test(e)) emails.add(e);
  }
  const text = stripTags(html);
  for (const m of text.matchAll(/[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}/g)) { const e = m[0].toLowerCase(); if (!BAD_EMAIL.test(e)) emails.add(e); }
  for (const m of html.matchAll(/href=["']tel:([^"']+)["']/gi)) {
    let p = ''; try { p = decodeURIComponent(m[1]).trim(); } catch (x) { p = m[1].trim(); }
    const d = p.replace(/\D/g, ''); if (d.length >= 9 && d.length <= 14) phones.add(p);
  }
  for (const m of text.matchAll(/(?:\+|00|0)\d[\d\s\-().]{8,16}\d/g)) {
    const p = m[0].trim(); const d = p.replace(/\D/g, ''); if (d.length >= 10 && d.length <= 13) phones.add(p);
  }
  return { emails: [...emails].slice(0, 5), phones: [...phones].slice(0, 5) };
}
function extractSocials(html, seed) {
  const s = Object.assign({ facebook: '', instagram: '', linkedin: '', twitter: '', youtube: '', tiktok: '' }, seed || {});
  for (const m of html.matchAll(/href=["'](https?:\/\/[^"']+)["']/gi)) {
    const u = m[1].replace(/&amp;/g, '&');
    if (!s.facebook && /facebook\.com\/[A-Za-z0-9.\-_]+/i.test(u) && !/sharer|share\.php|plugins|dialog|\/tr\?|\/policies|l\.facebook|facebook\.com\/(?:tr|sharer)/i.test(u)) s.facebook = u;
    if (!s.instagram && /instagram\.com\/[A-Za-z0-9._]+/i.test(u) && !/instagram\.com\/(?:p|reel|explore|accounts)\//i.test(u)) s.instagram = u;
    if (!s.linkedin && /linkedin\.com\/(?:company|in|school)\//i.test(u)) s.linkedin = u;
    if (!s.twitter && /(?:twitter|x)\.com\/(?!share|intent|home)[A-Za-z0-9_]+/i.test(u)) s.twitter = u;
    if (!s.youtube && /youtube\.com\/(?:channel|c|user|@)/i.test(u)) s.youtube = u;
    if (!s.tiktok && /tiktok\.com\/@/i.test(u)) s.tiktok = u;
  }
  return s;
}

const leads = $('Has Website?').all(0);
const YEAR = new Date().getFullYear();
const out = [];
$input.all().forEach((it, i) => {
  const lead = (leads[i] || {}).json || {};
  const r = it.json || {};
  const status = Number(r.statusCode || 0);
  const html = bodyOf(r);
  const base = lead.website || '';
  const blocked = [401, 403, 406, 429, 503].includes(status);
  const reachable = status >= 200 && status < 400 && html.length > 300;
  const issues = []; let score = 100; let siteStatus = '';
  let contacts = { emails: [], phones: [] }; let socials = Object.assign({}, lead.social_from_maps);
  let images = []; let contactUrl = ''; const tech = []; let title = ''; let metaDesc = ''; const sig = {};

  if (!reachable) {
    if (blocked) { score = 50; siteStatus = 'Unverified'; issues.push('Website blocks automated checks (HTTP ' + status + ') - could not be audited, verify manually'); }
    else { score = 10; siteStatus = 'Not Loading'; issues.push(status ? 'Website returned HTTP ' + status + ' (broken or down)' : 'Website did not respond (down, expired or very slow)'); }
  } else {
    contacts = extractContacts(html);
    socials = extractSocials(html, socials);
    const text = stripTags(html);
    title = ((html.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [])[1] || '').replace(/\s+/g, ' ').trim();
    metaDesc = (html.match(/<meta[^>]+name=["']description["'][^>]*content=["']([^"']*)["']/i) || html.match(/<meta[^>]+content=["']([^"']*)["'][^>]*name=["']description["']/i) || [])[1] || '';
    const h1 = (html.match(/<h1[\s>]/gi) || []).length;
    sig.https = /^https:/i.test(base);
    sig.viewport = /<meta[^>]+name=["']viewport["']/i.test(html);
    sig.form = /<form[\s>]/i.test(html);
    sig.whatsapp = /wa\.me|api\.whatsapp\.com|whatsapp/i.test(html);
    sig.chat = /tawk\.to|livechat|tidio|crisp\.chat|intercom|drift\.com|zopim|chatbot|botpress|manychat/i.test(html);
    sig.analytics = /googletagmanager|gtag\(|google-analytics|fbq\(|connect\.facebook\.net/i.test(html);
    sig.schema = /application\/ld\+json/i.test(html);
    sig.og = /property=["']og:/i.test(html);
    if (/wp-content|wp-includes/i.test(html)) tech.push('WordPress');
    if (/wixstatic|wix\.com/i.test(html)) tech.push('Wix');
    if (/cdn\.shopify|shopify/i.test(html)) tech.push('Shopify');
    if (/squarespace/i.test(html)) tech.push('Squarespace');
    if (/webflow/i.test(html)) tech.push('Webflow');
    if (/elementor/i.test(html)) tech.push('Elementor');
    if (/joomla/i.test(html)) tech.push('Joomla');
    if (/blogspot|blogger/i.test(html)) tech.push('Blogger');
    const imgSet = new Set();
    const og = (html.match(/property=["']og:image["'][^>]*content=["']([^"']+)["']/i) || html.match(/content=["']([^"']+)["'][^>]*property=["']og:image["']/i) || [])[1];
    if (og) imgSet.add(absUrl(og, base));
    for (const m of html.matchAll(/<img[^>]+(?:data-src|src)=["']([^"']+)["']/gi)) {
      const u = absUrl(m[1], base);
      if (u && /\.(jpe?g|png|webp)(\?|$)/i.test(u) && !/logo|icon|sprite|pixel|avatar|emoji|spinner|loader/i.test(u)) imgSet.add(u);
      if (imgSet.size >= 8) break;
    }
    images = [...imgSet].slice(0, 5);
    sig.img_count = (html.match(/<img[\s]/gi) || []).length;
    sig.img_missing_alt = (html.match(/<img(?![^>]*\balt=["'][^"']+["'])[^>]*>/gi) || []).length;
    const cy = html.match(/(?:©|&copy;|copyright)[^0-9]{0,30}((?:19|20)\d{2})(?:\s*[-–]\s*((?:19|20)\d{2}))?/i);
    sig.copyright_year = cy ? Number(cy[2] || cy[1]) : 0;
    const baseHost = (() => { try { return new URL(base).hostname; } catch (e) { return ''; } })();
    for (const m of html.matchAll(/<a[^>]+href=["']([^"'#]+)["'][^>]*>([\s\S]*?)<\/a>/gi)) {
      if (/contact/i.test(m[1]) || /contact/i.test(stripTags(m[2]))) {
        const u = absUrl(m[1], base);
        try { if (u && new URL(u).hostname === baseHost) { contactUrl = u; break; } } catch (e) {}
      }
    }
    const deduct = (pts, msg) => { score -= pts; issues.push(msg); };
    if (!sig.https) deduct(5, 'Website address is http:// (SSL/HTTPS not confirmed)');
    if (!sig.viewport) deduct(20, 'Not mobile-friendly (no responsive viewport tag)');
    if (!title) deduct(8, 'Missing page title (hurts Google ranking)');
    if (!metaDesc) deduct(10, 'Missing meta description (poor Google snippet)');
    if (h1 === 0) deduct(6, 'No H1 heading on the homepage');
    if (!sig.form) deduct(8, 'No contact/enquiry form on the homepage');
    if (!sig.whatsapp && !sig.chat) deduct(6, 'No WhatsApp button or live chat / chatbot');
    if (!sig.analytics) deduct(6, 'No analytics or ad-tracking installed (Google Analytics / Pixel)');
    if (!sig.schema) deduct(4, 'No structured data (schema) for local SEO');
    if (!sig.og) deduct(3, 'No social-sharing (Open Graph) tags');
    if (sig.img_count < 3) deduct(6, 'Very few images - site looks plain / thin');
    if (sig.img_count >= 4 && sig.img_missing_alt / sig.img_count > 0.5) deduct(5, 'Most images have no alt text (SEO + accessibility)');
    if (sig.copyright_year && sig.copyright_year < YEAR - 2) deduct(10, 'Footer copyright shows ' + sig.copyright_year + ' - site looks outdated');
    if (text.length < 1500) deduct(8, 'Very little text content on the homepage');
    if (!contacts.emails.length && !contacts.phones.length) deduct(10, 'No email or phone visible on the homepage');
    if (!Object.values(socials).some(Boolean)) deduct(8, 'No social media links on the website');
    if ((html.match(/<table[\s>]/gi) || []).length > 10 || /<marquee|<font[\s>]/i.test(html)) deduct(10, 'Old-style page code (tables / deprecated tags)');
    score = Math.max(0, Math.min(100, score));
    siteStatus = score >= 75 ? 'Good' : (score >= 50 ? 'Needs Improvement' : 'Poor');
  }
  out.push({ json: Object.assign({}, lead, {
    has_website: true,
    website_reachable: reachable,
    website_http_status: status,
    website_score: score,
    website_status: siteStatus,
    website_issues: issues,
    website_images: images,
    emails: contacts.emails,
    phones: lead.phone ? [lead.phone].concat(contacts.phones) : contacts.phones,
    social: socials,
    tech: tech.join(', '),
    site_title: title,
    meta_description: metaDesc,
    contact_url: contactUrl,
    website_signals: sig
  }) });
});
return out;

const BAD_EMAIL = /\.(png|jpe?g|gif|webp|svg|css|js|woff2?)$|sentry|wixpress|example\.|domain\.com|yourname|email@email|u003e|@2x/i;
const absUrl = (u, base) => { try { return new URL(u, base).href; } catch (e) { return ''; } };
const stripTags = (h) => h.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();
