  }
  return { emails: [...emails].slice(0, 5), phones: [...phones].slice(0, 5) };
}
function extractSocials(html, seed) {
  const s = Object.assign({ facebook: '', instagram: '', linkedin: '', twitter: '', youtube: '', tiktok: '' }, seed || {});
  for (const m of html.matchAll(/href=["'](https?:\/\/[^"']+)["']/gi)) {
    const u = m[1].replace(/&amp;/g, '&');
    if (!s.facebook && /facebook\.com\/[A-Za-z0-9.\-_]+/i.test(u) && !/sharer|share\.php|plugins|dialog|\/tr\?|\/policies|l\.facebook|facebook\.com\/(?:tr|sharer)/i.test(u)) s.facebook = u;
    if (!s.instagram && /instagram\.com\/[A-Za-z0-9._]+/i.test(u) && !/instagram\.com\/(?:p|reel|explore|accounts)\//i.test(u)) s.instagram = u;
