    if (!s.twitter && /(?:twitter|x)\.com\/(?!share|intent|home)[A-Za-z0-9_]+/i.test(u)) s.twitter = u;
    if (!s.youtube && /youtube\.com\/(?:channel|c|user|@)/i.test(u)) s.youtube = u;
    if (!s.tiktok && /tiktok\.com\/@/i.test(u)) s.tiktok = u;
  }
