const parsed = $('Parse Homepage').all();
const out = [];
$input.all().forEach((it, i) => {
  const base = (parsed[i] || {}).json || {};
  const html = bodyOf(it.json || {});
  let emails = (base.emails || []).slice();
  let phones = (base.phones || []).slice();
  let social = Object.assign({}, base.social);
  if (html.length > 300) {
    const c = extractContacts(html);
    emails = [...new Set(emails.concat(c.emails))].slice(0, 5);
    phones = [...new Set(phones.concat(c.phones))].slice(0, 6);
    social = extractSocials(html, social);
  }
  out.push({ json: Object.assign({}, base, { emails: emails, phones: phones, social: social }) });
});
return out;

return $input.all().map(it => {
  const l = it.json;
  return { json: Object.assign({}, l, {
    has_website: false,
    website_reachable: false,
    website_score: 0,
    website_status: 'No Website',
    website_issues: ['No own website found for this business'],
    website_images: l.maps_image ? [l.maps_image] : [],
    emails: [],
    phones: l.phone ? [l.phone] : [],
    social: Object.assign({}, l.social_from_maps),
    tech: '',
    contact_url: ''
  }) };
});

const req = $('Prepare Request').first().json;
const leads = $input.all().map(i => i.json);
const igUrl = (u) => {
  const m = String(u || '').match(/instagram\.com\/([A-Za-z0-9._-]+)/i);
  if (!m) return '';
  if (['p', 'reel', 'reels', 'explore', 'accounts', 'stories', 'tv'].includes(m[1].toLowerCase())) return '';
  return 'https://www.instagram.com/' + m[1] + '/';
};
const jobs = [];
if (req.check_social) {
  leads.forEach(l => {
