// ---- robust JSON reader (repairs trailing commas, stray text, code fences)
const parseAI = (txt) => {
  let t = String(txt || '').replace(/```json|```/gi, '').trim();
  const a = t.indexOf('{'), b = t.lastIndexOf('}');
  if (a < 0 || b <= a) return null;
  t = t.slice(a, b + 1);
  const noTrail = (s) => s.replace(/,(\s*[}\]])/g, '$1');
  const attempts = [
    (s) => s,
    (s) => noTrail(s),
    (s) => noTrail(s).replace(/[\u0000-\u001f]+/g, ' '),
    (s) => noTrail(s).replace(/[\u201c\u201d]/g, '"').replace(/[\u0000-\u001f]+/g, ' ')
  ];
  for (const f of attempts) { try { const o = JSON.parse(f(t)); if (o && typeof o === 'object') return o; } catch (e) {} }
  return null;
};

// ---- complete fallback plan built only from scraped facts
function fallbackPlan(l, email, phone) {
  const hasSite = !!l.has_website;
  const name = l.business_name;
