    const label = p.charAt(0).toUpperCase() + p.slice(1);
    if (x.status === 'Active') socialLines.push('Your ' + label + ' page is active (last post ' + x.days_inactive + ' days ago); we can help turn that activity into enquiries.');
    else socialLines.push('Your ' + label + ' page was last updated ' + x.days_inactive + ' days ago, which can reduce reach and trust.');
  });
  const text = issues.join(' ').toLowerCase();
  const pool = svcList.length ? svcList : ['Website Development', 'SEO', 'Social Media Management'];
  const pickBy = (re) => pool.filter(s => re.test(s));
  const chosen = [];
  const add = (a) => a.forEach(s => { if (!chosen.includes(s) && chosen.length < 4) chosen.push(s); });
  if (!hasSite || (l.website_score || 0) < 60) add(pickBy(/web|site|design|develop|landing|wordpress|shopify/i));
  if (!hasSite || /meta|h1|schema|title|alt text|analytics|open graph/.test(text)) add(pickBy(/seo|marketing|ads|google/i));
  if (/whatsapp|chat|form|email or phone/.test(text)) add(pickBy(/automation|chatbot|bot|whatsapp|crm|ai/i));
  const socialWeak = ['facebook', 'instagram'].some(p => sa[p] && (sa[p].status === 'Inactive' || sa[p].status === 'Slow')) || !Object.values(l.social || {}).some(Boolean);
  if (socialWeak) add(pickBy(/social|ugc|video|content|brand|creative|ads/i));
  if (!chosen.length) add(pool.slice(0, 2));
  const score = clamp((100 - (l.website_score || 0)) * 0.7 + (email ? 15 : 0) + (phone ? 10 : 0));
  const n = chosen.length || 1;
  const lowBase = hasSite ? ((l.website_score || 0) < 50 ? 400 : 250) : 400;
  const low = Math.round(lowBase * (1 + 0.5 * (n - 1)) / 50) * 50;
  const high = Math.round(low * 2.5 / 100) * 100;
  const comps = l.competitors || [];
  let ci = '';
  if (comps.length) {
    const names = comps.slice(0, 2).map(c => c.name + ' (' + (c.rating || '-') + ' stars, ' + (c.reviews || 0) + ' reviews)').join(' and ');
    const w = comps.filter(c => c.has_website).length;
    ci = 'Nearby ' + cat + ' businesses such as ' + names + ' are building visibility online' + (w ? ', and ' + w + ' of the top ' + comps.length + ' have their own website.' : ', and none of the top ' + comps.length + ' has its own website yet.');
  }
  const wf = hasSite ? issues.slice(0, 5) : ['We could not find a dedicated website for ' + name + ', so people searching online for ' + cat + ' services cannot easily find or trust you.'];
  const subject = cap(hasSite ? ((l.website_score || 0) < 60 ? 'Quick website improvements for ' + name : 'Ideas to grow ' + name + ' online') : 'Helping ' + name + ' get found online', 70);
  const whatsapp = 'Hi ' + name + ' team, this is ' + req.user_name + ' from ' + req.company + '. I looked at your online presence and noticed ' + (hasSite ? 'a few quick website improvements that could bring you more enquiries' : 'you do not have a dedicated website yet, which may be costing you new customers') + '. We help with ' + chosen.slice(0, 3).join(', ') + '. Would you be open to a quick chat?';
  return {
    lead_score: score,
    priority: score >= 70 ? 'high' : (score >= 40 ? 'medium' : 'low'),
    deal: money(low) + ' - ' + money(high),
    services: chosen,
    weak: issues.slice(0, 5).concat(socialLines).slice(0, 6),
    summary: name + ' has ' + (l.rating ? 'a ' + l.rating + '-star Google rating' : 'a Google listing') + (l.reviews ? ' with ' + l.reviews + ' reviews' : '') + ', but ' + (hasSite ? 'its website scores ' + (l.website_score || 0) + '/100' : 'it has no dedicated website') + '. ' + chosen.join(', ') + ' could help it win more customers online.',
    subject: subject,
    opening: 'I am ' + req.user_name + ' from ' + req.company + '. I recently researched ' + name + ' and noticed a few opportunities to strengthen your online presence.',
    website_findings: wf,
    social_findings: socialLines.slice(0, 3),
    competitor_insight: ci,
    solutions: chosen.map(s => ({ service: s, how_it_helps: serviceHelp(s) })),
    closing_cta: 'I would love to share a few quick ideas with you. Would you be open to a short call or a reply to this email this week?',
    whatsapp: whatsapp
  };
}

