  else if (email) channel = 'Email Only';
  else if (phone) channel = 'Phone/WhatsApp Only';
  else if (l.has_website) channel = 'Website Form Only';

  const fb = fallbackPlan(l, email, phone);
  const plan = mergePlan(ai, fb);
  const mail = buildEmail(l, plan.email);
  const wa = phone ? plan.whatsapp : '';
  const summary = plan.summary + (ai ? '' : ' [Auto-draft: AI reply was unreadable, please review]');

