  rows.push({ json: {
    Run_ID: req.run_id,
    Lead_ID: l.lead_id,
    Business_Name: l.business_name,
    Category: l.category,
    Lead_Type: leadType,
    Contact_Channel: channel,
    Website: l.website || '',
    Email: email,
    Phone: phone,
    WhatsApp_Link: waLink(phone, l.country),
    Address: l.address,
    Country: l.country,
    Google_Rating: l.rating,
    Google_Reviews: l.reviews,
    Google_Maps_URL: l.maps_url,
    Lead_Score: plan.lead_score,
    Priority: plan.priority,
    Estimated_Deal_Value: plan.deal,
    Recommended_Services: plan.services.join(', '),
    Weaknesses: plan.weak.join(' | '),
    Analysis_Summary: summary,
    Website_Score: l.has_website ? l.website_score : '',
    Website_Status: l.website_status,
    Website_Issues: (l.website_issues || []).join(' | '),
    Website_Images: (l.website_images || []).filter(Boolean).join('\n'),
    Tech_Stack: l.tech || '',
    Facebook_URL: s.facebook || '',
    Instagram_URL: s.instagram || '',
    LinkedIn_URL: s.linkedin || '',
    Twitter_URL: s.twitter || '',
    YouTube_URL: s.youtube || '',
    TikTok_URL: s.tiktok || '',
    Social_Status: l.social_summary || '',
    Facebook_Last_Post: (sa.facebook && sa.facebook.last_post) || '',
    Facebook_Days_Inactive: (sa.facebook && sa.facebook.days_inactive !== undefined) ? sa.facebook.days_inactive : '',
    Instagram_Last_Post: (sa.instagram && sa.instagram.last_post) || '',
    Instagram_Days_Inactive: (sa.instagram && sa.instagram.days_inactive !== undefined) ? sa.instagram.days_inactive : '',
    Competitors: comps,
    Email_Subject: plan.email.subject,
    Email_Body_Text: mail.text,
    Email_Body_HTML: mail.html,
    WhatsApp_Message: wa,
    Approval_Status: approval,
    Email_Status: emailStatus,
    Response_Status: 'No Reply',
    Sender_Name: req.company || req.user_name,
    Search_Query: req.search_query,
    Created_At: now.toISOString(),
    Email_Sent_At: '',
    Follow_Up_1_Date: addDays(3),
    Follow_Up_2_Date: addDays(7),
    Gmail_Thread_ID: ''
  } });
});
return rows;

const req = $('Prepare Request').first().json;
