const get = (n) => { try { const it = $(n).first(); return it ? it.json : null; } catch (e) { return null; } };
const out = (o) => [{ json: { response: o } }];
const acc = get('Check Sheet Access'), meta = get('Prepare Header Check'), rd = get('Read Header Row'), wr = get('Write Headers');
if (!acc || acc.statusCode !== 200 || !meta) {
  const code = acc && acc.statusCode;
  if (code === 404) return out({ ok: false, error: 'We could not find this sheet. Please check the link.' });
  return out({ ok: false, error: 'We cannot open this sheet. Please share it with the service email as Editor and try again.' });
}
const url = 'https://docs.google.com/spreadsheets/d/' + meta.sheet_id + '/edit';
if (wr) {
  if (wr.statusCode === 200) return out({ ok: true, sheet_id: meta.sheet_id, tab: meta.tab, title: meta.title, url: url, headers: 'created' });
  return out({ ok: false, error: 'We could not prepare this sheet. Please make sure it is shared with the service email as Editor (not Viewer).' });
}
const vals = (rd && rd.body && rd.body.values && rd.body.values[0]) || [];
if (vals.indexOf('Lead_ID') === -1) return out({ ok: false, error: 'The first row of this sheet already contains other headings. Please connect a new blank sheet.' });
return out({ ok: true, sheet_id: meta.sheet_id, tab: meta.tab, title: meta.title, url: url, headers: 'ok' });

