const ACCESS_CODES = ['ali'];
const raw = $input.first().json || {};
const b = raw.body || raw;
const s = (v) => (v === undefined || v === null) ? '' : String(v).trim();
const bad = (msg, code) => [{ json: { valid: false, status_code: code || 400, error: msg } }];
if (!ACCESS_CODES.includes(s(b.access_code))) return bad('Invalid access code.', 401);
const rx = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;
const to = s(b.to), subject = s(b.subject).replace(/[\r\n]+/g, ' ').slice(0, 150), html = s(b.html), text = s(b.text);
if (!rx.test(to)) return bad('Recipient email address is not valid.');
if (!subject) return bad('Subject is empty.');
if (!html && !text) return bad('Message is empty.');
if (html.length > 150000) return bad('Message is too large.');
const replyTo = rx.test(s(b.reply_to)) ? s(b.reply_to) : '';
const bodyHtml = html || ('<div style="font-family:Arial,sans-serif;white-space:pre-wrap">' + text.replace(/&/g,'&amp;').replace(/</g,'&lt;') + '</div>');
return [{ json: { valid: true, lead_id: s(b.lead_id), to: to, subject: subject, html: bodyHtml, sender_name: s(b.sender_name).slice(0, 80), reply_to: replyTo } }];

